package dev.studyforge.banking.application; import dev.studyforge.banking.domain.*; import org.junit.jupiter.api.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; class BankingCoreTest{@Test void commitsAtomicTransferAndHistory(){BankingCore b=BankingCore.inMemory(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC),UUID::randomUUID,FeeStrategy.noFee(),FeeStrategy.noFee(),List.of());AccountId a=new AccountId("a"),d=new AccountId("d");b.open(Account.builder(a,"A",Currency.getInstance("USD")).openingBalance(Money.of("10","USD")).build());b.open(Account.builder(d,"D",Currency.getInstance("USD")).build());b.transfer(new Transfer(a,d,Money.of("4","USD")));assertEquals(Money.of("6","USD"),b.account(a).balance());assertEquals(1,b.history().size());} @Test void notificationFailureIsReportedAfterCommit(){BankingCore b=BankingCore.inMemory(Clock.systemUTC(),UUID::randomUUID,FeeStrategy.noFee(),FeeStrategy.noFee(),List.of(t->{throw new IllegalStateException("down");}));AccountId a=new AccountId("a");b.open(Account.builder(a,"A",Currency.getInstance("USD")).build());assertThrows(NotificationDeliveryException.class,()->b.deposit(new Deposit(a,Money.of("1","USD"))));assertEquals(Money.of("1","USD"),b.account(a).balance());} @Test void duplicateAccountIsRejected(){BankingCore b=BankingCore.inMemory(Clock.systemUTC(),UUID::randomUUID,FeeStrategy.noFee(),FeeStrategy.noFee(),List.of());Account a=Account.builder(new AccountId("a"),"A",Currency.getInstance("USD")).build();b.open(a);assertThrows(DuplicateAccountException.class,()->b.open(a));}}
